  "No se completó el pago": ["Payment wasn’t completed", "O pagamento não foi concluído", "Le paiement n’a pas abouti", "Il pagamento non è stato completato", "Zahlung nicht abgeschlossen"],
  "Actualiza la app desde Google Play para poder suscribirte.": ["Update the app from Google Play to subscribe.", "Atualize a app no Google Play para poder subscrever.", "Mettez l’app à jour via Google Play pour vous abonner.", "Aggiorna l’app da Google Play per abbonarti.", "Aktualisiere die App über Google Play, um zu abonnieren."],
  "Tu cuenta aún no está activada.": ["Your account isn’t activated yet.", "A sua conta ainda não está ativada.", "Votre compte n’est pas encore activé.", "Il tuo account non è ancora attivo.", "Dein Konto ist noch nicht aktiviert."],
  "{n} días gratis": ["{n} days free", "{n} dias grátis", "{n} jours gratuits", "{n} giorni gratis", "{n} Tage gratis"],
  "Al acabar los {n} días gratis, Google Play cobra {precio}. Cancela antes desde Google Play y no se cobra nada.": ["After the {n} free days, Google Play charges {precio}. Cancel before in Google Play and nothing is charged.", "No fim dos {n} dias grátis, o Google Play cobra {precio}. Cancele antes no Google Play e não se cobra nada.", "Après les {n} jours gratuits, Google Play prélève {precio}. Annulez avant dans Google Play et rien n’est prélevé.", "Dopo i {n} giorni gratis, Google Play addebita {precio}. Annulla prima da Google Play e non paghi nulla.", "Nach {n} Gratistagen berechnet Google Play {precio}. Vorher in Google Play kündigen, dann wird nichts berechnet."],
  "Google Play cobra {precio}. Cancela cuando quieras desde Google Play.": ["Google Play charges {precio}. Cancel any time in Google Play.", "O Google Play cobra {precio}. Cancele quando quiser no Google Play.", "Google Play prélève {precio}. Annulez quand vous voulez dans Google Play.", "Google Play addebita {precio}. Annulla quando vuoi da Google Play.", "Google Play berechnet {precio}. Jederzeit in Google Play kündbar."],
  "Empezar {n} días gratis": ["Start {n} free days", "Começar {n} dias grátis", "Commencer {n} jours gratuits", "Inizia {n} giorni gratis", "{n} Gratistage starten"],
  "El pago lo hace Google Play con tu cuenta de Google.": ["Payment is made by Google Play with your Google account.", "O pagamento é feito pelo Google Play com a sua conta Google.", "Le paiement est effectué par Google Play avec votre compte Google.", "Il pagamento lo fa Google Play con il tuo account Google.", "Die Zahlung läuft über Google Play mit deinem Google-Konto."],
  "Gestionar o cancelar en Google Play": ["Manage or cancel in Google Play", "Gerir ou cancelar no Google Play", "Gérer ou annuler dans Google Play", "Gestisci o annulla su Google Play", "In Google Play verwalten oder kündigen"],
  "No se pudo canjear": ["Couldn’t redeem", "Não foi possível resgatar", "Échange impossible", "Impossibile riscattare", "Einlösen fehlgeschlagen"],
  "¿Te han regalado la app?": ["Were you gifted the app?", "Ofereceram-lhe a app?", "On vous a offert l’app ?", "Ti hanno regalato l’app?", "Wurde dir die App geschenkt?"],
  "Código de regalo": ["Gift code", "Código de oferta", "Code cadeau", "Codice regalo", "Geschenkcode"],
