  // Comparte tu día (11-10-2026)
  "HOY HE REPARTIDO": ["TODAY I DELIVERED", "HOJE ENTREGUEI", "AUJOURD’HUI J’AI LIVRÉ", "OGGI HO CONSEGNATO", "HEUTE ZUGESTELLT"],
